INSERT OR IGNORE INTO products (id, slug, name, price, compare_at, category, tagline, description, serves, prep_note, images, includes, badges, reviews, featured, active, position) VALUES ('p1', 'despertar-sencillo', 'Despertar Sencillo', 50000, NULL, 'clasicos', 'El primer desayuno de la casa. Panqueques, jugo y una nota escrita a mano.', 'Nuestro desayuno de entrada: mini panqueques recién hechos con miel, jugo de naranja exprimido esa misma mañana y fruta cortada al momento. Va con cubiertos, servilleta de tela y una tarjeta que escribimos a mano con tu mensaje.', 1, 'Se arma la madrugada de la entrega. Pedidos hasta las 8:00 p. m. del día anterior.', '["/img/french-toast-banano.jpg","/img/jugo-naranja.jpg","/img/yogurt-granola.jpg"]', '[{"name":"Jugo de naranja natural","detail":"350 ml, exprimido el mismo día"},{"name":"Mini panqueques con miel","detail":"4 unidades"},{"name":"Fruta de temporada","detail":"corte del día"},{"name":"Mermelada y mantequilla","detail":"porción individual"},{"name":"Cubiertos y servilleta","detail":"incluidos"},{"name":"Tarjeta personalizada","detail":"escrita a mano con tu mensaje"}]', '["Más vendido"]', '[]', 1, 1, 0);
INSERT OR IGNORE INTO products (id, slug, name, price, compare_at, category, tagline, description, serves, prep_note, images, includes, badges, reviews, featured, active, position) VALUES ('p2', 'manana-dulce', 'Mañana Dulce', 60000, NULL, 'dulces', 'Yogurt griego, fresa, kiwi y galleta artesanal.', 'Para quien prefiere empezar liviano pero con azúcar honesta: yogurt griego con fresa y kiwi frescos, galleta artesanal horneada por una panadería del barrio y jugo de naranja.', 1, 'Viaja en frío hasta tu puerta.', '["/img/yogurt-granola.jpg","/img/smoothie-fresa.jpg","/img/bowl-frutas-coco.jpg"]', '[{"name":"Jugo de naranja natural","detail":"350 ml"},{"name":"Yogurt griego","detail":"vaso de 200 g"},{"name":"Fresas y kiwi","detail":"cortados al momento"},{"name":"Galleta artesanal","detail":"horneada el mismo día"}]', '[]', '[]', 1, 1, 1);
INSERT OR IGNORE INTO products (id, slug, name, price, compare_at, category, tagline, description, serves, prep_note, images, includes, badges, reviews, featured, active, position) VALUES ('p3', 'zen-morning', 'Zen Morning', 65000, NULL, 'saludables', 'Jugo verde, tostadas de aguacate y frutos secos.', 'El desayuno de los que entrenan temprano. Jugo verde de espinaca, manzana y pepino; tostadas de pan de masa madre con aguacate; frutos secos y una tabla de fruta con kiwi, piña y arándanos.', 1, 'El jugo verde se hace 40 minutos antes de salir.', '["/img/aguacate-huevo-dark.jpg","/img/bowl-aguacate.jpg","/img/bowl-frutas-azul.jpg"]', '[{"name":"Jugo verde","detail":"espinaca, manzana y pepino · 350 ml"},{"name":"Tostadas de aguacate","detail":"2 unidades en masa madre"},{"name":"Frutos secos","detail":"almendra, marañón y nuez"},{"name":"Fruta fresca","detail":"kiwi, piña y arándanos"}]', '["Sin azúcar añadida"]', '[]', 1, 1, 2);
INSERT OR IGNORE INTO products (id, slug, name, price, compare_at, category, tagline, description, serves, prep_note, images, includes, badges, reviews, featured, active, position) VALUES ('p4', 'desayuno-mini-explorador', 'Desayuno Mini Explorador', 70000, NULL, 'infantiles', 'Panqueques con chispas, brocheta de frutas y una sorpresa adentro.', 'Pensado para niños. Panqueques con toppings a elegir (miel, chispas de chocolate, rodajas de banano), brocheta de frutas, jugo, un yogurt pequeño y una sorpresa escondida en la caja.', 1, 'Cuéntanos la edad en las notas del pedido y ajustamos la sorpresa.', '["/img/french-toast-banano.jpg","/img/banano-rosa.jpg","/img/jugo-naranja.jpg"]', '[{"name":"Panqueques","detail":"4 unidades"},{"name":"Toppings","detail":"miel, chispas de chocolate y banano en rodajas"},{"name":"Brocheta de frutas","detail":"2 unidades"},{"name":"Jugo","detail":"250 ml"},{"name":"Yogurt pequeño","detail":"150 g"},{"name":"Sorpresa","detail":"juguete o dulce sorpresa según edad"}]', '["Para niños"]', '[]', 0, 1, 3);
INSERT OR IGNORE INTO products (id, slug, name, price, compare_at, category, tagline, description, serves, prep_note, images, includes, badges, reviews, featured, active, position) VALUES ('p5', 'cesta-campestre', 'Cesta Campestre', 75000, NULL, 'clasicos', 'Panadería, queso campesino, waffle integral y té.', 'Una cesta larga para desayunar sin prisa: pan integral, croissant, waffle integral, queso campesino, buñuelitos, fruta fresca con kiwi, fresa y mango, y una selección de tés.', 2, 'Va en cesta de mimbre que se queda con quien lo recibe.', '["/img/waffles-frutas.jpg","/img/panes-artesanales.jpg","/img/tostada-huevo.jpg"]', '[{"name":"Jugo natural","detail":"350 ml"},{"name":"Pan integral y croissant","detail":"de panadería local"},{"name":"Waffle integral","detail":"1 unidad"},{"name":"Queso campesino","detail":"porción de 150 g"},{"name":"Fruta fresca","detail":"kiwi, fresa y mango"},{"name":"Selección de tés","detail":"3 sobres"},{"name":"Buñuelitos","detail":"4 unidades"}]', '["Alcanza para dos"]', '[]', 1, 1, 4);
INSERT OR IGNORE INTO products (id, slug, name, price, compare_at, category, tagline, description, serves, prep_note, images, includes, badges, reviews, featured, active, position) VALUES ('p6', 'detox-box', 'Detox Box', 80000, 92000, 'saludables', 'Jugo de coco y jengibre, shot de limón, granola y cítricos.', 'La caja de los lunes. Jugo de coco con jengibre y limón, frutas cítricas, yogurt griego con granola, un shot de jengibre y limón, galleta integral de avena y bolitas de queso.', 1, 'El shot viaja aparte, en botella sellada.', '["/img/bowl-frutas-coco.jpg","/img/bowl-frutas-azul.jpg","/img/smoothie-fresa.jpg"]', '[{"name":"Jugo de coco, jengibre y limón","detail":"350 ml"},{"name":"Frutas cítricas","detail":"naranja, mandarina y toronja"},{"name":"Yogurt griego con granola","detail":"200 g"},{"name":"Shot de jengibre y limón","detail":"60 ml"},{"name":"Galleta integral de avena","detail":"2 unidades"},{"name":"Bolitas de queso","detail":"4 unidades","needsReview":true}]', '["Sin azúcar añadida"]', '[]', 0, 1, 5);
INSERT OR IGNORE INTO products (id, slug, name, price, compare_at, category, tagline, description, serves, prep_note, images, includes, badges, reviews, featured, active, position) VALUES ('p7', 'amanecer-romantico', 'Amanecer Romántico', 90000, NULL, 'romanticos', 'Fresas con crema, croissants rellenos de chocolate y jugo de frutos rojos.', 'El desayuno de aniversario. Jugo de frutos rojos y jugo de naranja, fresas con crema, croissants rellenos de chocolate, tabla de quesos y uvas verdes. Se puede pedir con globo y vela.', 2, 'Se entrega con tarjeta manuscrita. Globo y vela se agregan como adicionales.', '["/img/croissant.jpg","/img/smoothie-fresa.jpg","/img/bowl-frutas-coco.jpg"]', '[{"name":"Jugo de frutos rojos","detail":"350 ml"},{"name":"Jugo de naranja","detail":"350 ml"},{"name":"Fresas con crema","detail":"copa de 250 g"},{"name":"Croissants rellenos de chocolate","detail":"2 unidades"},{"name":"Tabla de quesos","detail":"3 quesos"},{"name":"Uvas verdes","detail":"racimo"}]', '["Para dos"]', '[]', 1, 1, 6);
INSERT OR IGNORE INTO products (id, slug, name, price, compare_at, category, tagline, description, serves, prep_note, images, includes, badges, reviews, featured, active, position) VALUES ('p8', 'brunch-gourmet', 'Brunch Gourmet', 100000, 115000, 'gourmet', 'Dos jugos, tabla de galletas y quesos, avena con tocineta.', 'El más completo de la carta. Dos jugos, tabla de galletas y quesos, avena con tocineta, fruta fresca, uvas y arándanos, y bolitas de queso. Alcanza cómodo para dos personas.', 2, 'La avena viaja en termo para llegar caliente.', '["/img/tostada-huevo.jpg","/img/waffles-frutas.jpg","/img/panes-artesanales.jpg"]', '[{"name":"Dos jugos naturales","detail":"350 ml cada uno"},{"name":"Tabla de galletas y quesos","detail":"4 quesos"},{"name":"Avena con tocineta","detail":"porción caliente","needsReview":true},{"name":"Fruta fresca","detail":"corte del día"},{"name":"Uvas y arándanos","detail":"porción"},{"name":"Bolitas de queso","detail":"6 unidades","needsReview":true}]', '["El más completo"]', '[]', 0, 1, 7);

