INSERT OR IGNORE INTO posts (id, slug, title, excerpt, cover, author, date, body, published) VALUES ('b1', 'como-armamos-una-caja', 'Cómo armamos una caja a las 4 de la mañana', 'La fruta se corta a las 4:10. El jugo se exprime a las 4:40. La tarjeta se escribe de último, para que la tinta no se corra.', '/img/tabla-ingredientes.jpg', 'Equipo Aurora', '2026-07-28', 'La cocina abre a las 3:40 a. m. No es romanticismo: un desayuno que sale a las 6:00 tiene que armarse en ese orden exacto o llega tibio.

Primero la fruta. Se corta entera, nunca la noche anterior, porque la piña suelta agua y moja la galleta. Después el pan: lo recogemos de la panadería de la esquina a las 4:30, todavía caliente.

El jugo va de último entre los líquidos. Exprimido a las 4:40, sellado a las 4:45, en frío hasta que sube al carro.

La tarjeta se escribe al final. Con tinta de gel, que seca rápido, y siempre a mano. Es lo primero que lee quien abre la caja.', 1);
INSERT OR IGNORE INTO posts (id, slug, title, excerpt, cover, author, date, body, published) VALUES ('b2', 'que-regalar-segun-la-ocasion', 'Qué desayuno regalar según la ocasión', 'Cumpleaños, disculpa, aniversario, primer día de trabajo. Cada uno pide una caja distinta.', '/img/bowl-aguacate.jpg', 'Equipo Aurora', '2026-07-15', 'Un aniversario pide Amanecer Romántico: fresas con crema y croissants rellenos hacen el trabajo emocional solos.

Un cumpleaños de oficina pide Cesta Campestre, porque alcanza para compartir y nadie queda mirando.

Una disculpa pide algo sencillo y bien escrito. Despertar Sencillo con una tarjeta larga funciona mejor que la caja más cara con dos líneas.

Un primer día de trabajo pide Zen Morning. Nadie quiere entrar a una reunión con azúcar encima.', 1);
INSERT OR IGNORE INTO posts (id, slug, title, excerpt, cover, author, date, body, published) VALUES ('b3', 'la-tarjeta-importa-mas-que-la-caja', 'La tarjeta importa más que la caja', 'Leemos miles de mensajes al año. Los que funcionan tienen una cosa en común: son específicos.', '/img/banano-rosa.jpg', 'Equipo Aurora', '2026-06-30', '«Feliz cumple, te quiero mucho» está bien. «Feliz cumple. Todavía me acuerdo del bus que perdimos en Villa de Leyva» es otra cosa.

La diferencia es la especificidad. Un detalle concreto convierte un mensaje genérico en algo que la persona guarda.

Tienes 300 caracteres en el configurador. Es suficiente para un recuerdo, un chiste interno o una frase que solo ustedes dos entienden. Úsalos.', 1);

